USE canetevive360;

INSERT INTO DISTRITO(nombre,descripcion) VALUES 
('Asia','ubicado en la provincia de Cañete, destaca en la costa peruana por su combinación de exclusividad veraniega, atractivos naturales y patrimonio histórico. Sus principales puntos de interés incluyen extensos balnearios, el concurrido Boulevard de Asia, el ecosistema estacional de las Lomas de Asia y el complejo arqueológico Huaca Malena, VISITANOS'), 
('Calango','Calango es uno de los 16 distritos que conforman la provincia de Cañete en la región Lima, Perú. Conocido popularmente como la "capital de la manzana delicia" y de los ricos camarones, se ubica a unas 2 horas al sureste de Lima, VISITANOS'), 
('Cerro Azul','Cerro Azul es un tradicional balneario, distrito y antiguo puerto pesquero ubicado en la provincia de Cañete (departamento de Lima), aproximadamente en el kilómetro 132 de la Panamericana Sur, VISITANOS'), 
('Chilca','El distrito de Chilca, ubicado en la provincia de Cañete (a tan solo una hora y media al sur de Lima), es un destino turístico muy popular que combina misticismo, salud, historia y aventura, VISITANOS'), 
('Coayllo','Coayllo es uno de los distritos más antiguos de la provincia de Cañete, ubicado a unas dos horas al sur de Lima (a unos 100 km de la capital y a 17 km de la Panamericana Sur). Conocido históricamente como “La Tierra de los Nísperos”, combina un valioso legado prehispánico y colonial con hermosos paisajes de valle y lomas, VISITANOS'), 
('Imperial','El distrito de Imperial, ubicado en la provincia de Cañete (departamento de Lima), es reconocido como la capital comercial del valle de Cañete. Combina una intensa actividad económica con un valioso legado histórico, agrícola y cultural a pocas horas de la capital, VISITANOS'), 
('Lunahuana','Lunahuaná es una villa y capital del distrito homónimo, ubicada en la provincia de Cañete (región Lima), a unos 183 a 185 kilómetros al sur de Lima (aproximadamente de 2 horas y media a 3 horas de viaje en auto). Es considerada la capital turística y cultural de la provincia, VISITANOS'), 
('Mala','El distrito de Mala, ubicado en la provincia de Cañete (departamento de Lima) a la altura del kilómetro 86 de la Panamericana Sur (a solo una hora y media de la capital), es un destino turístico que combina mar, campo, historia y una reconocida tradición gastronómica, VISITANOS'), 
('Nuevo Imperial','El distrito de Nuevo Imperial, perteneciente a la provincia de Cañete en el departamento de Lima, es conocido como el "Eterno manantial de vida" y uno de los puntos clave en el camino hacia la sierra y el valle de Lunahuaná, VISITANOS'), 
('Pacaran','Pacarán, conocido como "La Tierra de la Eterna Primavera y el Buen Pisco", es un pintoresco distrito ubicado en la provincia de Cañete, a solo 15 o 17 kilómetros al este de Lunahuaná (aprox. 200 km al sureste de Lima). Se alza a unos 700 metros sobre el nivel del mar a orillas del río Cañete, VISITANOS'), 
('Quilmana','Quilmaná, conocido como la «Capital de la Cordialidad y la Amistad», es un pintoresco distrito ubicado en la provincia de Cañete (Lima), a unas dos horas y media de la capital. Destaca por su ambiente apacible, su vocación agrícola y una oferta turística familiar en crecimiento, VISITANOS'), 
('San Antonio','El distrito de San Antonio, ubicado en la provincia de Cañete (a unas 2 horas al sur de Lima, en el kilómetro 80 de la Panamericana Sur), es una excelente opción de escapada corta que combina naturaleza, historia, fe y buena gastronomía, VISITANOS'), 
('San Luis','El distrito de San Luis es uno de los 16 distritos de la provincia de Cañete, en la región Lima, y es considerado el corazón cultural e histórico del valle. Se encuentra ubicado a unas dos horas y media al sur de Lima (aproximadamente a 138 km), VISITANOS'), 
('Santa Cruz de Flores','Santa Cruz de Flores es un pintoresco distrito de la provincia de Cañete, en el departamento de Lima, reconocido oficialmente como la «Capital del Vino y el buen Pisco». Se encuentra ubicado a aproximadamente una hora de la ciudad de Lima, por lo que es un destino ideal para una escapada de fin de semana, VISITANOS'),
('San Vicente','San Vicente de Cañete, capital de la provincia de Cañete en la región Lima (a unos 144 km al sur de Lima, a 2 horas de viaje), es conocida como el «Corazón del Sur Chico». Combina historia prehispánica, herencia afroperuana, arquitectura colonial y republicana, y una reconocida tradición vitivinícola y gastronómica, VISITANOS'),
('Zuñiga','El distrito de Zúñiga, ubicado en la provincia de Cañete (región Lima, Perú), es conocido como la «Ciudad del Eterno Sol Radiante» gracias a su clima cálido y despejado durante todo el año, VISITANOS');

INSERT INTO CATEGORIA(nombre) VALUES ('Aventura'),('Gastronomia'), ('Cultura');

INSERT INTO atractivo(id_distrito,id_categoria,nombre,descripcion,direccion,latitud,longitud) VALUES
('01','02','Boulevard de Asia (Sur Plaza, km 97.5)','Principal centro comercial, gastronómico y de entretenimiento al aire libre del sur chico, con restaurantes, tiendas y vida nocturna.','Carretera Panamericana Sur Km 97.5, Asia','-12.78583','-76.57278'),
('01','01','Playa Pasamayito','Extensa playa de arena fina y oleaje moderado, ideal para caminatas costeras, descanso y deportes de tabla.','Altura Km 103.5 de la Panamericana Sur, Asia','-12.82861','-76.53889'),
('01','03','Huaca Malena','Complejo arqueológico prehispánico de adobe (culturas Wari e Ychsma) célebre por el hallazgo de fardos funerarios y textilería fina.','Anexo La Esquina, Valle de Asia (altura Km 101 Panamericana Sur)','-12.78194','-76.55611'),
('01','01','Lomas de Asia','Ecosistema costero estacional que reverdece en invierno con flora silvestre (flor de Amancaes, tara) y rutas de senderismo.','Sector Cerro Colorado / Este del Km 98 Panamericana Sur, Asia','-12.74833','-76.53194'),
('01','02','Restaurante El Piloto (Boulevard de Asia)','Tradicional restaurante cañetano famoso por su comida criolla, chicharrones y platos marinos en el patio gastronómico del Boulevard.','Sur Plaza Boulevard de Asia, Panamericana Sur Km 97.5, Asia','-12.78528','-76.57222'),

('02','03','Iglesia de Calango (Virgen de la Candelaria)','Templo principal frente a la plaza del distrito, centro de devoción a la Virgen de la Candelaria y arquitectura tradicional de valle.','Plaza de Armas de Calango s/n, Calango','-12.52556','-76.54472'),
('02','03','Piedra Coyllur Sayana','Enorme bloque lítico prehispánico con petroglifos grabados (figuras antropomorfas y zoomorfas) asociado a antiguos cultos astronómicos.','Sector Retama / Margen del río Mala, a 1.5 km del pueblo de Calango','-12.53278','-76.55361'),
('02','03','Zona Arqueológica La Vuelta','Asentamiento prehispánico de piedra y barro ubicado en las laderas del valle medio del río Mala con recintos y terrazas.','Anexo La Vuelta, Carretera Mala - Calango Km 21, Calango','-12.53833','-76.56556'),
('02','02','Valle de la manzana delicia','Extensos huertos frutales dedicados al cultivo de la emblemática manzana delicia, además de paltos y lúcumos.','Carretera Mala - Calango Km 18 - Km 25, Valle de Calango','-12.52750','-76.54806'),
('02','01','Río Mala y balneario de Calango','Ribera del río Mala con aguas cristalinas, zonas de campamento, recreos campestres y pesca artesanal de camarones.','Ribera del Río Mala, altura Av. Principal s/n, Calango','-12.52694','-76.54611'),

('03','03','Muelle de Cerro Azul','Histórico muelle artesanal inaugurado en 1924, ícono turístico del balneario ideal para paseos, pesca deportiva y avistamiento de aves.','Final del Malecón José Olaya s/n, Cerro Azul','-13.02583','-76.48361'),
('03','03','Sitio Arqueológico El Huarco','Monumental complejo administrativo y defensivo Inca-Huarco construido en piedra y adobe sobre los acantilados frente al mar.','Cerro Camacho / Extremo sur de la bahía de Cerro Azul','-13.03056','-76.48472'),
('03','01','Playa El Fraile (Puerto Viejo)','Ensenada rocosa y tranquila situada al sur del cerro Camacho, muy apreciada por su paisaje natural y aguas serenas.','Sector Puerto Viejo, al sur del complejo El Huarco, Cerro Azul','-13.03611','-76.48528'),
('03','03','Casona British Sugar','Antigua casona de arquitectura republicana vinculada al auge agroindustrial azucarero y portuario de finales del siglo XIX.','Calle Alfonso Ugarte / Malecón José Olaya, Cerro Azul','-13.02389','-76.48028'),
('03','02','Puerto pesquero de Cerro Azul','Zona de desembarque artesanal y corredor gastronómico marino reconocido por sus cebiches, parihuelas y jaleas frescas.','Malecón José Olaya cuadra 1 - 3, Cerro Azul','-13.02472','-76.48139'),

('04','01','Lagunas medicinales de Chilca (La Milagrosa, La Mellicera y La Encantada)','Conjunto de lagunas salinas con barros y aguas mineromedicinales altamente mineralizadas.','Centro Poblado Las Salinas, altura Km 67.5 Panamericana Sur, Chilca','-12.53639','-76.74389'),
('04','01','Playa Yaya','Playa amplia de arena oscura y oleaje tranquilo ubicada frente al sector de Las Salinas, popular para el camping y deportes náuticos.','Final de la Av. Las Salinas (altura Km 67.5 Panamericana Sur), Chilca','-12.54333','-76.74861'),
('04','03','Sitio Arqueológico de Bandurria (Pirámide Lapa Lapa)','Complejo arqueológico monumental en el cerro Lapa Lapa con estructuras escalonadas de piedra y vistas panorámicas del valle.','Sector Cerro Lapa Lapa, Km 62 Panamericana Sur, Chilca','-12.50222','-76.74750'),
('04','03','Iglesia Nuestra Señora de la Asunción de Chilca','Joya de la arquitectura barroca mestiza del siglo XVIII declarada Monumento Histórico Nacional, con imponentes torres gemelas.','Plaza de Armas de Chilca s/n (Jr. Independencia), Chilca','-12.51861','-76.73750'),
('04','02','Helados de higo de Chilca','Emblema gastronómico artesanal elaborado a base de los higos negros cultivados en los hoyos agrícolas tradicionales del distrito.','Alrededores de la Plaza de Armas y Av. Nicolás de Piérola, Chilca','-12.51944','-76.73806'),

('05','03','Templo Colonial de Coayllo','Iglesia histórica de fachada blanca y campanario de adobe que conserva el trazado colonial del valle de Omas-Coayllo.','Plaza de Armas de Coayllo s/n, Coayllo','-12.72806','-76.46222'),
('05','03','Sitios Arqueológicos de Coayllo: Uquira, Quialla y Saquillao','Conjunto de complejos administrativos y residenciales prehispánicos (Inca-Coayllo) edificados en piedra y tapia a lo largo del valle.','Carretera Asia - Coayllo Km 15 al Km 22 (Sector Uquira), Coayllo','-12.73583','-76.48694'),
('05','02','Valle de los nísperos','Fértil corredor agrícola reconocido por su producción de nísperos dulces, licores artesanales, mermeladas y néctares.','Carretera Asia - Coayllo Km 18 - Km 24, Valle de Coayllo','-12.72972','-76.46583'),
('05','01','Lomas de Coayllo','Colinas costero-andinas que desarrollan vegetación estacional en los meses húmedos, ideales para trekking y observación de fauna.','Cerros aledaños al sector Cata y Uquira, Coayllo','-12.71111','-76.47500'),
('05','01','Mirador de Coayllo','Punto elevado natural que ofrece una vista panorámica completa del casco urbano, el templo colonial y los huertos de nísperos.','Cerro Mirador (acceso norte desde la Plaza de Armas), Coayllo','-12.72583','-76.46167'),

('06','03','Plaza de Armas e iglesia de Imperial','Núcleo cívico y comercial de Imperial, presidido por la parroquia Nuestra Señora del Carmen de tonalidad ocre y estilo neocolonial.','Av. 28 de Julio / Jr. El Carmen s/n, Imperial','-13.06083','-76.35222'),
('06','03','Fortaleza de Ungará','Imponente bastión militar prehispánico (Huarco-Inca) erigido sobre un peñón rocoso que domina el valle bajo del río Cañete.','Centro Poblado Ungará, Carretera Cañete - Lunahuaná Km 6, Imperial','-13.04694','-76.31056'),
('06','03','Casa de la Cultura de Imperial','Espacio dedicado a la difusión del arte, música afroperuana, historia local y actividades cívicas del distrito.','Jr. 2 de Mayo / Alrededores de la Plaza de Armas, Imperial','-13.06167','-76.35278'),
('06','02','Mercado de Imperial','Principal centro de abastos de la provincia, famoso por sus jugos frescos, comida criolla tradicional y productos agrícolas del valle.','Av. Oscar R. Benavides / Jr. Sucre, Imperial','-13.06250','-76.35417'),
('06','01','Río Cañete y campos de Imperial','Paisaje rural irrigado por acequias centenarias con cultivos de algodón, maíz, vid y frutales junto al cauce del río Cañete.','Sector Bocas / Rivera del Río Cañete, Imperial','-13.05833','-76.32222'),

('07','03','Complejo Arqueológico de Incahuasi','Extensa ciudadela incaica construida por Túpac Yupanqui como réplica ceremonial del Cusco durante la conquista del señorío Huarco.','Anexo Paullo, Carretera Cañete - Lunahuaná Km 29.5, Lunahuaná','-13.01694','-76.17417'),
('07','01','Puente Colgante de Catapalla','Pintoresco puente peatonal de madera y cables sobre el río Cañete que conecta los viñedos y bodegas del anexo Catapalla.','Anexo Catapalla, Carretera Lunahuaná - Yauyos Km 45, Lunahuaná','-12.93194','-76.11806'),
('07','01','Canotaje en el río Cañete','Actividad emblemática de turismo de aventura con rápidos de clase II a IV a lo largo de las aguas cristalinas del río Cañete.','Sector Socsi - Puente Catapalla (Carretera Km 33 - Km 45), Lunahuaná','-12.96389','-76.13611'),
('07','02','Bodega D\' la Cruz','Bodega vitivinícola tradicional donde se elaboran piscos puros, acholados y vinos artesanales con recorridos guiados y catas.','Anexo Catapalla s/n, Carretera Lunahuaná - Yauyos Km 45, Lunahuaná','-12.93083','-76.11722'),
('07','03','Iglesia Santiago Apóstol y Plaza de Armas','Templo colonial del siglo XVII con altar mayor de estilo barroco y fachada rojiza, ubicado frente a la plaza principal del distrito.','Plaza de Armas de Lunahuaná s/n (Jr. Grau), Lunahuaná','-12.96222','-76.13389'),

('08','03','Iglesia Matriz San Pedro de Mala','Principal templo católico del distrito, reconstruido en estilo neoclásico con torres amarillas y detalles blancos frente a la plaza.','Plaza de Armas de Mala s/n (Jr. Real), Mala','-12.65806','-76.63056'),
('08','03','Plaza de Armas de Mala (Glorieta Oriental)','Plaza cívica rodeada de jardines y palmeras, destacada por su glorieta central de inspiración oriental con techo rojizo.','Entre Jr. Real, Jr. Sullana y Av. Marchand, Mala','-12.65861','-76.63083'),
('08','01','Playa Bujama','Balneario costero de arena clara y extensas orillas ubicado a pocos minutos del centro urbano de Mala, ideal para veraneo y surf.','Altura Km 90.5 de la Panamericana Sur, Mala','-12.71667','-76.62500'),
('08','03','Sitio Arqueológico El Salitre','Complejo monumental prehispánico de piedra y adobe situado sobre una elevación natural cerca de la desembocadura del río Mala.','Sector El Salitre, altura Km 88 Panamericana Sur, Mala','-12.69556','-76.64306'),
('08','02','Bodega Castillo','Tradicional bodega maleña dedicada a la producción artesanal de piscos, vinos y macerados de frutas típicas del valle.','Sector Dignidad Nacional / Valle de Mala, Mala','-12.65278','-76.62444'),

('09','03','Santuario de la Madre del Amor Hermoso','Importante centro de peregrinación católica de la Prelatura de Yauyos-Cañete, rodeado de amplios jardines y arquitectura moderna.','Carretera Cañete - Lunahuaná Km 8.5, Nuevo Imperial','-13.06639','-76.30194'),
('09','01','Bosque de Protección Aledaño a la Bocatoma del Canal Nuevo Imperial','Área natural protegida de 18.11 hectáreas que resguarda la infraestructura hidráulica y la biodiversidad ribereña del río Cañete.','Sector La Bocatoma, altura Km 11 Carretera Cañete - Lunahuaná','-13.05389','-76.27556'),
('09','03','Canal El Túnel Grande','Obra de ingeniería hidráulica excavada en roca viva a inicios del siglo XX para irrigar las pampas agrícolas de Imperial y Nuevo Imperial.','Sector Cerro Candela / Bocas del Canal Nuevo Imperial','-13.05556','-76.28333'),
('09','01','Manantiales de Nuevo Imperial','Afloramientos naturales de agua dulce alimentados por filtraciones del valle alto, rodeados de vegetación ribereña y aves locales.','Sector Carmen Alto / Baja, Nuevo Imperial','-13.07139','-76.31111'),
('09','02','Campos de cultivo del valle','Extensas áreas agrícolas productoras de mandarinas, uvas, paltas, espárragos y panllevar que definen el paisaje del distrito.','Valle de Nuevo Imperial (Sector Pueblo Nuevo de Conta)','-13.07500','-76.31806'),

('10','03','Iglesia San Francisco de Asís','Pintoresca iglesia de fachada fucsia intenso y molduras blancas frente a la plaza principal, patrona de la festividad distrital.','Plaza de Armas de Pacarán s/n, Pacarán','-12.86694','-76.05750'),
('10','03','Sitio Arqueológico de San Marcos','Vestigios prehispánicos con terrazas agrícolas, recintos de piedra y estructuras defensivas en la margen del río Cañete.','Anexo San Marcos, Carretera Lunahuaná - Yauyos Km 53, Pacarán','-12.87806','-76.06889'),
('10','01','Puentes colgantes sobre el río Cañete','Puentes peatonales tradicionales que cruzan el río Cañete hacia los anexos agrícolas y miradores naturales de Pacarán.','Acceso sur desde la Plaza de Armas hacia el río Cañete, Pacarán','-12.86861','-76.05833'),
('10','02','Bodega Buena Vista (Don Nepta)','Reconocida bodega familiar especializada en la destilación artesanal de piscos de uva quebranta, italia y vinos de la zona.','Carretera Cañete - Yauyos Km 55.5, Pacarán','-12.86556','-76.05583'),
('10','01','Canotaje en el río Cañete (Pacarán)','Tramo alto y panorámico del descenso en balsa por el río Cañete, caracterizado por aguas limpias y cañones rocosos.','Ribera del Río Cañete, sector Puente Pacarán (Km 55), Pacarán','-12.86944','-76.05917'),

('11','03','Parroquia Nuestra Señora del Rosario','Templo principal del distrito ubicado frente a la plaza cívica, centro de las celebraciones patronales de octubre.','Plaza de Armas de Quilmaná s/n (Av. Lima), Quilmaná','-12.94833','-76.38278'),
('11','01','Parque Zonal Chavín de Huántar','Famoso parque temático recreativo con réplicas a escala de las maravillas del mundo, cabezas clavas, laguna artificial y zoológico.','Av. Lima s/n (entrada norte del distrito), Quilmaná','-12.94222','-76.38611'),
('11','03','Cerro Hueco','Formación rocosa natural con una oquedad característica en su cima y vestigios arqueológicos en sus laderas, símbolo local.','Sector Roldán / Este de Quilmaná (a 3 km del centro)','-12.94167','-76.35417'),
('11','01','Lomas de Quilmaná','Cadena de cerros costeros que durante la temporada invernal se cubren de neblina y vegetación silvestre ideal para caminatas.','Zona norte de Quilmaná (límite con Asia y Coayllo)','-12.89167','-76.41667'),
('11','02','Campos agrícolas de Quilmaná','Vastas irrigaciones de cítricos (mandarinas, naranjas), paltos y algodón fruto del proyecto de irrigación de las pampas.','Pampas de Quilmaná (alrededores de la Carretera Imperial - Quilmaná)','-12.96111','-76.37500'),

('12','03','Iglesia de San Antonio','Templo parroquial dedicado a San Antonio de Padua, ubicado en el corazón histórico del distrito frente a su plaza principal.','Plaza de Armas de San Antonio s/n (Jr. Pedro Beltrán), San Antonio','-12.63972','-76.65361'),
('12','03','Sitio Arqueológico La Ollería','Complejo prehispánico asociado a la producción alfarera y ocupación de la cultura Ychsma e Inca en el valle bajo de Mala.','Sector La Ollería / Cerro La Ollería, San Antonio','-12.63472','-76.64722'),
('12','01','Playa León Dormido','Icónica playa reconocida por su formación rocosa que asemeja la silueta de un león recostado frente al océano Pacífico.','Altura Km 80 de la Panamericana Sur, San Antonio','-12.62583','-76.67139'),
('12','01','Humedales de Puerto Viejo','Ecosistema costero de lagunas y totorales que alberga decenas de especies de aves residentes y migratorias.','Altura Km 71 - Km 73 de la Panamericana Sur, San Antonio','-12.57361','-76.70417'),
('12','02','Valle y cultivos de San Antonio','Huertos tradicionales de manzanos, plátanos maleños, paltos y productos de panllevar irrigados por el río Mala.','Sector Esquivel / Camino a León Dormido, San Antonio','-12.63611','-76.65833'),

('13','03','Iglesia de San Luis','Templo histórico del distrito, punto de encuentro cultural y religioso de la comunidad afroperuana de San Luis de Cañete.','Plaza de Armas de San Luis s/n (Jr. Comercio), San Luis','-13.04444','-76.42583'),
('13','03','Exhacienda Casa Blanca','Antigua hacienda colonial y republicana de arquitectura señorial vinculada a la historia de la población afrodescendiente en Cañete.','Centro Poblado Casa Blanca (altura Km 141 Panamericana Sur), San Luis','-13.02972','-76.41611'),
('13','03','Templo de Santa Efigenia (La Quebrada)','Santuario dedicado a Santa Efigenia, santa negra venerada cada septiembre con festivales de arte negro, zapateo y música tradicional.','Centro Poblado La Quebrada (altura Km 139 Panamericana Sur), San Luis','-13.01694','-76.40417'),
('13','02','Restaurante El Piloto (San Luis)','Sede original de este clásico restaurante de carretera famoso por su pan con chicharrón, tamales cañetanos y comida criolla.','Carretera Panamericana Sur Km 141.5, San Luis','-13.04194','-76.42806'),
('13','01','Río Cañete y campos de San Luis','Tierras fértiles del valle bajo donde se cultiva caña de azúcar, algodón y frutales, surcadas por canales históricos.','Sector La Quebrada / Santa Bárbara, San Luis','-13.05139','-76.43333'),

('14','03','Plaza e iglesia de Santa Cruz de Flores','Plaza cívica con pérgola y monumento central junto a su templo parroquial, epicentro de la vendimia y el festival del vino.','Plaza de Armas de Santa Cruz de Flores s/n, Santa Cruz de Flores','-12.62028','-76.63528'),
('14','02','Bodega Sarcay','Prestigiosa bodega boutique reconocida internacionalmente por sus piscos artesanales de uva negra criolla, quebranta e italia.','Anexo San Vicente de Azpitia s/n, Santa Cruz de Flores','-12.60139','-76.60556'),
('14','01','Caserío San Vicente de Azpitia (Balcón del Cielo)','Mirador natural suspendido sobre el valle del río Mala, célebre por sus restaurantes campestres, vistas panorámicas y deportes de aventura.','Carretera Flores - Azpitia Km 4.5, Anexo Azpitia, Santa Cruz de Flores','-12.59944','-76.60417'),
